import React, { Fragment } from "react";
import {
  Col,
  Form,
  FormGroup,
  Label,
  Input,
  FormText,
  CustomInput
} from "reactstrap";
import { Button } from "@material-ui/core";
export default function FileUpload() {
  return (
    <Fragment>
      <Form>
        <Button
          style={{ marginLeft: "1%" }}
          variant="contained"
          color="primary"
        >
          Load File
        </Button>

        <Col>
          <CustomInput
            type="file"
            id="exampleCustomFileBrowser"
            name="customFile"
            label="Upload Goal Geometry File - ASCII STL Files Only"
          />
        </Col>
      </Form>
    </Fragment>
  );
}
